const list=document.getElementById('resultList'),status=document.getElementById('status'),count=document.getElementById('resultCount');let locationPoint=null,points=[],locationLabel='Twoja lokalizacja',searchVersion=0,locationRequest=0,nearbyVersion=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function homeIcon(name){return `<svg class="home-icon" aria-hidden="true"><use href="#icon-${name}"/></svg>`}
function pointLabel(number){const last=number%10,lastTwo=number%100;return number+' '+(number===1?'punkt':last>=2&&last<=4&&(lastTwo<12||lastTwo>14)?'punkty':'punktów')}
let map=null,markers=[];const mapStatus=document.getElementById('mapStatus');
if(window.L){map=L.map('aedMap',{scrollWheelZoom:false}).setView([52.0,19.2],6);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map)}else{mapStatus.textContent='Nie udało się załadować mapy. Lista AED pozostaje dostępna.'}
const dialog=document.createElement('dialog');dialog.className='aed-dialog';dialog.setAttribute('aria-labelledby','aedDialogTitle');document.body.appendChild(dialog);
function openAED(p){window.aedStopPhoto();const photo=window.aedPhotoBlock(p);dialog.innerHTML=`<div class="aed-modal-head"><span class="aed-modal-label">${homeIcon('heart')} DEFIBRYLATOR AED</span><button class="aed-modal-close" aria-label="Zamknij" type="button">×</button></div><div class="aed-modal-body"><h2 id="aedDialogTitle">${esc(p.name)}</h2><p class="aed-modal-address">⌖ &nbsp; ${esc(p.address)}</p><div class="aed-modal-details"><div><small>DOSTĘPNOŚĆ</small><strong>${esc(availabilityLabel(p.hours))}</strong><p>${esc(p.access)}</p></div><div><small>GODZINY DOSTĘPU</small><p>${esc(p.hours)}</p></div>${p.description?`<div><small>JAK ZNALEŹĆ AED</small><p>${esc(p.description)}</p></div>`:''}</div>${photo}</div><div class="aed-modal-footer"><a class="aed-navigate" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.lat)},${encodeURIComponent(p.lon)}&travelmode=walking" target="_blank" rel="noopener noreferrer">Wyznacz trasę do AED</a><p>Trasa otworzy się w Google Maps</p><button type="button" id="modalReport" class="report-toggle">Zgłoś problem z tym AED</button></div>`;dialog.querySelector('#modalReport').onclick=()=>document.dispatchEvent(new CustomEvent('aed-report-request',{detail:p}));dialog.querySelector('.aed-modal-close').addEventListener('click',()=>dialog.close());if(!dialog.open)dialog.showModal();window.aedLoadPhoto(dialog,p)}
dialog.addEventListener('close',()=>window.aedStopPhoto());
dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
function updateMap(){const guide=document.getElementById('mapGuide');if(guide)guide.hidden=Boolean(locationPoint);if(!map)return;markers.forEach(marker=>map.removeLayer(marker));markers=[];const bounds=[];if(locationPoint){const here=L.circleMarker([locationPoint.lat,locationPoint.lon],{radius:9,color:'#fff',weight:3,fillColor:'#278aee',fillOpacity:1}).addTo(map).bindPopup(esc(locationLabel));markers.push(here);bounds.push([locationPoint.lat,locationPoint.lon])}points.forEach((p,index)=>{const icon=L.divIcon({className:'aed-map-icon',html:homeIcon('heart'),iconSize:[36,36],iconAnchor:[18,36],popupAnchor:[0,-32]});const marker=L.marker([p.lat,p.lon],{icon,title:p.name}).addTo(map).on('click',()=>openAED(p));markers.push(marker);bounds.push([p.lat,p.lon]);marker.aedIndex=index});if(bounds.length>1)map.fitBounds(bounds,{padding:[35,35],maxZoom:16});else if(bounds.length)map.setView(bounds[0],15);mapStatus.textContent=points.length?pointLabel(points.length)+' w pobliżu':locationPoint?'Wybrana lokalizacja':'Wybierz swoją lokalizację'}
const availabilityLabel=h=>({open:'Godziny wskazują: otwarte',closed:'Godziny wskazują: zamknięte',unknown:'Dostępność nieznana'})[aedAvailability(h)];
function render(){
  count.textContent=pointLabel(points.length);
  list.innerHTML=points.length?points.map((p,index)=>{
    const availability=aedAvailability(p.hours);
    const distance=Number.isFinite(p.distance)?(p.distance<1?Math.round(p.distance*1000)+' m':p.distance.toFixed(1).replace('.',',')+' km'):'Odległość nieznana';
    return `<article class="result"><div class="result-heading"><span class="cardicon">${homeIcon('heart')}</span><div class="result-info"><h3><button type="button" class="result-open" data-open="${index}" aria-label="Szczegóły AED: ${esc(p.name)}">${esc(p.name)}</button></h3><p class="result-address">${esc(p.address||'Adres niepodany')}</p></div><span class="distance-pill">${esc(distance)}</span></div><div class="result-detail-row"><span class="availability availability-${availability}"><span aria-hidden="true"></span>${esc(availabilityLabel(p.hours))}</span><span class="result-hours" title="${esc(p.hours||'Godziny dostępu nieznane')}">${homeIcon('clock')}<span>${esc(p.hours||'Godziny dostępu nieznane')}</span></span></div>${p.description?`<p class="result-description">${esc(p.description)}</p>`:''}<div class="result-footer"><button class="report-toggle" type="button" data-report="${index}">Zgłoś problem</button><a class="result-navigate" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.lat)},${encodeURIComponent(p.lon)}&travelmode=walking">${homeIcon('pin')}Wyznacz trasę</a></div></article>`;
  }).join(''):`<div class="results-empty"><span class="empty-map-icon">${homeIcon('pin')}</span><h3>${locationPoint?'Brak wyników w tej okolicy':'Wskaż miejsce. Znajdź najbliższy AED.'}</h3><p>${locationPoint?'Spróbuj wyszukać inny adres. Brak wyników nie oznacza braku urządzeń.':'Użyj swojej lokalizacji lub wpisz adres powyżej. Tutaj pojawią się pobliskie urządzenia i informacje o dostępie.'}</p></div>`;
}
list.addEventListener('click',event=>{const button=event.target.closest('[data-open]');if(button&&points[Number(button.dataset.open)])openAED(points[Number(button.dataset.open)])});
async function nearby(){if(!locationPoint)return;const request=++nearbyVersion;status.textContent='Szukamy pobliskich AED…';updateMap();try{const response=await fetch(`/api/nearby?lat=${encodeURIComponent(locationPoint.lat)}&lon=${encodeURIComponent(locationPoint.lon)}`);if(!response.ok)throw Error();const data=await response.json();if(request!==nearbyVersion)return;points=data.points;window.aedRegistryVersion=data.review_revision+':'+data.moderation_revision;render();updateMap();const source=data.source==='registry'?'Rejestr AED · źródła i zatwierdzone zgłoszenia':data.source==='warsaw'?'Urząd m.st. Warszawy (CC BY)':'© autorzy OpenStreetMap (ODbL)';status.textContent=points.length?`Źródło: ${source}. Odległość w linii prostej; dostępność może się zmienić.`:`Źródło: ${source}. Nie znaleziono AED w promieniu 10 km. Brak wyników nie oznacza braku urządzeń.`}catch{if(request!==nearbyVersion)return;points=[];render();updateMap();status.textContent='Nie udało się pobrać danych. Sprawdź połączenie i spróbuj ponownie.'}}
function locate(){const request=++locationRequest;if(!navigator.geolocation){status.textContent='Geolokalizacja jest niedostępna.';return}status.textContent='Ustalamy lokalizację…';navigator.geolocation.getCurrentPosition(p=>{if(request!==locationRequest)return;locationLabel='Twoja lokalizacja';locationPoint={lat:p.coords.latitude,lon:p.coords.longitude};nearby()},()=>{if(request===locationRequest)status.textContent='Nie udało się ustalić lokalizacji. Zezwól na dostęp albo wpisz adres.'},{timeout:10000,maximumAge:60000})}
render();locate();document.getElementById('browse').onclick=()=>document.getElementById('aedMap').scrollIntoView();document.getElementById('adminBtn').onclick=()=>{window.location.href='/admin/map'};document.getElementById('locate').onclick=()=>{document.getElementById('aedMap').scrollIntoView();if(locationPoint)nearby();else locate()};async function search(){const input=document.getElementById('search').value.trim(),choices=document.getElementById('searchChoices');if(input.length<2){status.textContent='Wpisz miejscowość lub adres.';return}const request=++searchVersion;++locationRequest;++nearbyVersion;choices.innerHTML='';status.textContent='Szukamy adresu…';try{const response=await fetch('/api/geocode?q='+encodeURIComponent(input));if(!response.ok)throw Error();const data=await response.json();if(request!==searchVersion)return;if(!data.results.length){status.textContent='Nie znaleziono adresu. Spróbuj w formacie: Warszawa, Krucza 25.';return}const selectPoint=async item=>{locationLabel=data.approximate?'Przybliżony wynik: '+item.label:'Szukane miejsce: '+item.label;locationPoint={lat:item.lat,lon:item.lon};choices.innerHTML='';await nearby();const note=data.approximate?'Nie znaleziono numeru budynku. Pokazujemy przybliżone położenie ulicy: ':'Szukane miejsce: ';status.textContent=note+item.label+'. '+status.textContent;mapStatus.textContent=data.approximate?'Przybliżona lokalizacja ulicy':locationLabel;document.getElementById('aedMap').scrollIntoView({behavior:'smooth',block:'center'})};if(data.results.length===1){await selectPoint(data.results[0]);return}status.textContent='Wybierz właściwe miejsce. Wyniki: GUGiK.';data.results.forEach(item=>{const button=document.createElement('button');button.type='button';button.className='search-choice';button.textContent=item.label+(data.approximate?' (przybliżony)':'');button.addEventListener('click',()=>selectPoint(item));choices.appendChild(button)})}catch{if(request===searchVersion)status.textContent='Nie udało się wyszukać adresu. Sprawdź połączenie i spróbuj ponownie.'}}document.getElementById('searchBtn').onclick=search;document.getElementById('search').addEventListener('keydown',e=>{if(e.key==='Enter')search()});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
